const envs = [vars.env || undefined, ...(vars.compare ? vars.compare.split(',').map(s => s.trim()) : [])];
const rows = [];
for (const env of envs) {
  const r = await tools.consul_service({ name: vars.service, env }).catch(e => ({ error: e.message }));
  if (r.error) { rows.push({ env: env || '(default)', error: r.error }); continue; }
  for (const i of r.instances || []) { let commit = null; try { commit = JSON.parse(i.version || '{}').git?.commit?.id || null; } catch {} rows.push({ env: env || '(default)', node: i.node, status: i.status, version: i.meta?.version || null, commit }); }
}
const versions = [...new Set(rows.filter(r => r.version).map(r => `${r.version}${r.commit ? '@' + r.commit : ''}`))];
test('a version was found in every environment', () => expect(rows.filter(r => r.error).map(r => `${r.env}: ${r.error}`)).toEqual([]));
return { service: vars.service, same: versions.length ? versions.length === 1 : null, versions, instances: rows };
